    roleplay_prompts: [
      "Tại 응급실 (cấp cứu) — context panic. Diễn tập câu mở đầu với y tá triage: '심한 가슴 통증이 있어요' (đau ngực nhiều) hoặc '갑자기 호흡이 어려워요' (đột nhiên khó thở) — ngắn, factual, urgent. Tiếng Hàn keep ngắn dù căng thẳng.",
      "Bác sĩ hỏi medical history bằng technical Korean ('과거 병력', '복용 중인 약'). Diễn tập câu yêu cầu translation help: '죄송하지만 의학 용어는 잘 모릅니다. 영어로 설명해 주실 수 있나요?' — không xin lỗi quá đà.",
      "Dược sĩ giải thích cách uống thuốc (3x/ngày, sau ăn, 5 ngày). Diễn tập câu confirm bằng cách nhắc lại: '하루 3번, 식후, 5일이요. 맞나요?' — verification step để chắc chắn không hiểu nhầm.",
    ],
    register_notes:
      "Medical context = formal but warm. 해요체 với 간호사 (y tá), 접수원 (lễ tân), 약사 (dược sĩ). 하십시오체 với 의사 (bác sĩ) và trong 응급실 (cấp cứu — heightened formality). Cách xưng hô: 의사 = '선생님' (LUÔN 선생님, KHÔNG '의사님'); 간호사 = '간호사님'; 약사 = '약사님'. Khi mô tả triệu chứng: dùng past tense factual: '어제부터 ~했어요' (từ hôm qua em đã ~), '~ 시간 후에 시작됐어요' (bắt đầu ~ tiếng sau). Tránh dramatic words: '죽을 것 같아요' (em sắp chết — overstate, mất credibility), '너무 너무 아파요' (đau vô cùng — Hàn ưa specific scale). Tốt hơn: chỉ vào điểm đau, dùng scale 1-10 nếu được hỏi. Khi không hiểu medical term: '죄송하지만, 그 단어 영어로 뭐예요?' (Xin lỗi, từ đó tiếng Anh là gì?) — Hàn doctor majority biết English medical vocabulary. // TODO native review: '비보험 진료' (uninsured consultation) — confirm this is the term clinics use for foreign tourists.",
    idiom_glosses: [
      { idiom: "식은땀이 나다", literal: "đổ mồ hôi lạnh", meaning: "đổ mồ hôi lạnh — triệu chứng + ẩn dụ sợ hãi", example: "통증이 심해서 식은땀이 났어요." },
      { idiom: "한걸음에 달려가다", literal: "một bước chạy đến", meaning: "vội chạy đến (context cấp cứu)", example: "응급실로 한걸음에 달려갔어요." },
      { idiom: "차도가 보이다", literal: "thấy chuyển biến", meaning: "thấy hồi phục / cải thiện", example: "약 먹고 차도가 보였어요." },
      { idiom: "몸살이 나다", literal: "lên cơn đau mỏi cơ thể", meaning: "đau mỏi toàn thân do kiệt sức (chẩn đoán phổ biến ở Hàn)", example: "여행이 힘들어서 몸살이 났어요." },
    ],
    cultural_notes_vi:
      "Y tế Hàn cho du khách: (1) Du khách KHÔNG có bảo hiểm Hàn (NHIS) → trả full fee. Chi phí ước: phòng khám ~30,000-50,000원 (~600k-1tr VND), thuốc ~10,000-30,000원 (~200-600k VND). Bảo hiểm du lịch Việt thường reimburse — giữ HẾT receipts. (2) Có ARC visa (E-7, D-2, F visa), bạn có NHIS → trả 30%. (3) Pharmacy + bác sĩ TÁCH BIỆT ở Hàn (khác Việt). Bác sĩ kê 처방전 (đơn thuốc) → bạn bring đến 약국 → dược sĩ phát thuốc. KHÔNG bypass — illegal. (4) 응급실 (ER) là chỉ cho thực sự emergency. Đi ER cho cảm thường = bị từ chối hoặc charged ER rate (8x phòng khám rate). (5) Pharmacy '약국' marker chữ '약' đỏ — ở 90% subway exit + main streets. (6) Many Korean doctors speak basic medical English. International clinics ở Itaewon, Gangnam có English-fluent staff (ví dụ: Severance International Healthcare Center). (7) Nếu serious: gọi 1339 — Korea medical hotline, English service.",
    tip_advice_vi:
      "Trước khi đi Hàn: (1) Mua bảo hiểm du lịch VN — claim back 80-100% medical fee với receipts. (2) Lưu list dị ứng + thuốc đang dùng bằng tiếng Anh + tiếng Hàn: 'I am allergic to ___' = '저는 ___ 알레르기가 있어요'. Print + ảnh trong điện thoại. (3) Lưu Korean translation của symptoms thường gặp: 두통 (đau đầu), 복통 (đau bụng), 설사 (tiêu chảy), 발열 (sốt), 어지러움 (chóng mặt). (4) Mang theo emergency meds: ibuprofen + thuốc tiêu chảy — không cần đi clinic cho minor issues. Tại clinic: (a) Mang hộ chiếu + thẻ bảo hiểm du lịch; (b) Đến trước giờ open (9am thường) — short queue; (c) Pay tại counter sau visit; (d) Hỏi receipt + diagnosis paper bằng English nếu được — quan trọng cho insurance claim. Sau visit: (a) Nếu không recover trong 24h → quay lại; (b) Nếu xấu đi → 응급실 ngay, không chờ; (c) Submit insurance claim với passport+receipt+diagnosis paper trong 30 ngày về VN.",
    exercises: [
      { type: "fill-blank", question: "___이 있어서 페니실린은 못 먹어요.", answer: "알레르기" },
      {
        type: "matching",
        pairs: [
          { hangul: "식은땀이 나다", meaning: "đổ mồ hôi lạnh" },
          { hangul: "한걸음에 달려가다", meaning: "vội chạy đến" },
          { hangul: "차도가 보이다", meaning: "thấy hồi phục" },
          { hangul: "몸살이 나다", meaning: "đau mỏi cơ thể" },
        ],
        instruction: "Nối thành ngữ với nghĩa",
      },
      { type: "translation", vietnamese: "Phí khám bao nhiêu ạ?", hangul: "진료비는 얼마예요?" },
    ],
