    roleplay_prompts: [
      "Tài xế từ chối stop tại điểm đến, cố ý đi xa hơn 2 ngã tư. Diễn tập câu YÊU CẦU stop CỨNG: '여기서 세워 주세요. 도착했어요' (stop here, we've arrived) repeat 2-3 lần nếu cần. Nếu vẫn không stop → '경찰에 신고하겠어요' (will report police) — escalation cuối cùng nhưng work.",
      "Đến destination nhưng tài xế đòi cash only mặc dù taxi có card reader. Diễn tập câu chỉ ra evidence: '기사님 차에 카드 단말기가 있는데요. 카드 결제 부탁드려요' (your car has card reader; please accept card). Hàn taxi BẮT BUỘC accept card by law — cash only = scam.",
      "Sau ride bị overcharge, gọi Kakao Taxi customer service report. Diễn tập câu báo cáo: thời gian ride, biển số xe (plate number — luôn lưu khi vào), số tiền đúng vs số tiền charged, mô tả route detour. Cấu trúc factual, kèm timestamp.",
    ],
    register_notes:
      "Taxi context: 해요체 với 기사님. Gọi tài xế bằng '기사님' (driver-honorific) — KHÔNG '아저씨' (uncle — too informal cho service context, có thể nghe condescending). Khi pushback về route: dùng map evidence ('Naver 지도에는 ~' — on Naver Maps it shows ~) — Hàn drivers respect data evidence hơn intuition challenge. Phrase soft pushback: '한 번 더 확인해 주실 수 있어요?' (could you check once more?) — gives driver face-saving opportunity to correct without admitting mistake. Khi escalate: '경찰에 신고하겠어요' (will report to police) — last resort phrase, rất serious — dùng khi sure scam và driver từ chối correction. Sau ride: ALWAYS lấy 영수증 (receipt) — for dispute resolution. Phrases vàng: '미터기 확인해 주세요' (please check meter); '영수증 부탁드려요' (receipt please); '여기서 세워 주세요' (stop here please); '직진해 주세요' (go straight please). // TODO native review: '심야 할증' (night surcharge) — verify current Seoul taxi night-rate hours and percentage.",
    idiom_glosses: [
      { idiom: "바가지를 쓰다", literal: "đội cái bầu", meaning: "bị chặt chém / bị tính giá ép cao", example: "관광객이라고 바가지를 쓸 뻔했어요." },
      { idiom: "에둘러 가다", literal: "đi vòng vèo", meaning: "đi đường vòng / không trực tiếp", example: "기사가 일부러 에둘러 갔어요." },
      { idiom: "한 푼이 아쉽다", literal: "một xu cũng tiếc", meaning: "tiếc từng đồng / phải tiết kiệm", example: "여행 마지막 날이라 한 푼이 아쉬워요." },
      { idiom: "발 빠르게 대처하다", literal: "phản ứng chân nhanh", meaning: "phản ứng nhanh / xử lý kịp thời", example: "미터기를 발 빠르게 확인했어요." },
    ],
    cultural_notes_vi:
      "Seoul taxi system: (1) 95%+ tài xế honest — chỉ minority scam tourists. Đa phần ở Myeongdong, Itaewon, Hongdae — areas đông tourist; (2) BAR LAW: tất cả taxi ở Hàn BẮT BUỘC accept card payment. Cash-only = vi phạm luật, có thể report; (3) Meter rates 2026 Seoul: base 4,800원 (first 1.6km), +100원 per 132m, +100원 per 30sec idle. Night surcharge (00:00-04:00): +20%. Outside-Seoul surcharge: +20%. Toll roads passed: customer pays. Highest legitimate rate: ~25-30,000원 cho ride 30km within Seoul; (4) Apps: KakaoTaxi (most common, có English), Tada (premium), Uber (limited). App rides có complaint button — easier dispute; (5) Hotline khiếu nại: 120 (Seoul Dasan call center, English support); 1330 (Korea Tourism, English/Chinese/Japanese). Mẹo phòng ngừa: (a) Always note plate number trước khi vào; (b) Open Naver Maps + start navigation đến destination — tài xế thấy bạn track route ít dare detour; (c) Use Kakao Taxi app — dispute proof tự động qua app; (d) Refuse 'special service' ('I'll show you scenic route', 'special tour rate') — these = scams; (e) Có thể tự pull up route bằng Naver + show driver: 'Naver에서는 이 길이라고 나와요' (Naver shows this route). Recovery sau scam: receipt + plate number + screenshot route → submit qua app or 120 hotline → refund usual trong 7-14 ngày.",
    tip_advice_vi:
      "5 chiến lược phòng tránh taxi scam ở Seoul: (1) USE APP (KakaoTaxi/Uber) — fixed price visible, complaint history, không bị refuse short rides. Avoid hailing street taxi nếu mới đến Hàn; (2) NOTE PLATE NUMBER khi vào — chụp ảnh plate trước khi sit down (5 giây habit). Hàn taxi plate format: 서울XX 1234 (Seoul) hoặc tỉnh khác. Tài xế thấy = đỡ defensive; (3) NAVIGATE YOURSELF — open Naver Maps + start navigation. Tài xế thấy phone screen tracking = ít dare detour. Nếu deviate: '이 방향이 맞아요?' (this direction right?); (4) WATCH METER — should be ON từ giây đầu, KHÔNG nên có 추가 buttons pressed (ngoài start). Note initial 4,800원 rate. Final fare = meter only (KHÔNG +random surcharges); (5) ASK RECEIPT — '영수증 주세요' — even if no dispute, tax record + insurance claim. Khi gặp dispute: (a) STAY CALM — argue calm hơn fast resolution; (b) USE EVIDENCE: meter screenshot, GPS history, plate number; (c) CALL 120 nếu serious — Seoul Dasan English service mediates với driver realtime; (d) PAY first then report — refusing pay = legal trouble; instead pay overcharged amount + dispute later qua hotline → refund. Sau dispute: report qua KakaoTaxi app (nếu app ride) → screenshot route + receipt → submit. Refund time 7-14 ngày. Driver gets warning + may lose license nếu repeat offender.",
    exercises: [
      { type: "fill-blank", question: "기사님, 이 ___이 맞아요?", answer: "길" },
      {
        type: "matching",
        pairs: [
          { hangul: "바가지를 쓰다", meaning: "bị chặt chém / tính giá ép" },
          { hangul: "에둘러 가다", meaning: "đi đường vòng" },
          { hangul: "한 푼이 아쉽다", meaning: "tiếc từng đồng" },
          { hangul: "발 빠르게 대처하다", meaning: "phản ứng kịp thời" },
        ],
        instruction: "Nối thành ngữ với nghĩa",
      },
      { type: "translation", vietnamese: "Giá cước cao quá. Anh kiểm tra đồng hồ giúp em.", hangul: "요금이 너무 많이 나왔어요. 미터기 확인해 주세요." },
    ],
